"""architecture 内部：先计算尺度，提交图纸，失败时局部修改；最多三次模型调用。"""

from copy import deepcopy
import json

from langchain_core.tools import tool
from pydantic import TypeAdapter, ValidationError

from app.design.facts import Clearances, DesignEdit, DesignFacts, StairSizing
from app.design.resolve_facts import COLLECTIONS, calculate_stair, inspect_facts
from app.llm.client import create_llm
from app.llm.invocation import invoke_llm, stream_llm, merge_token_usage
from app.rag.trace import llm_trace_scope
from app.utils.json_extractor import extract_json_object


def _tool_schema(field, schema):
    definitions = schema.pop("$defs", {})
    return {"type":"object","additionalProperties":False,"properties":{field:schema},
            "required":[field],"$defs":definitions}


def apply_design_edits(document, changes):
    """在副本上按实体 ID 与字段路径修改；整批成功才返回。"""
    candidate = deepcopy(document)
    for edit in TypeAdapter(list[DesignEdit]).validate_python(changes):
        parts = [part.replace("~1","/").replace("~0","~") for part in edit.path[1:].split("/")]
        if parts[0] in COLLECTIONS and len(parts)==1 and edit.op!="append":
            raise ValueError("不能整体替换或删除实体数组；请修改具体实体或字段")
        if parts[0] in COLLECTIONS:
            if len(parts)==1:
                candidate.setdefault(parts[0],[])
            else:
                rows = candidate.get(parts[0],[])
                index = next((i for i,row in enumerate(rows) if isinstance(row,dict) and row.get("id")==parts[1]),None)
                if index is None:
                    raise ValueError(f"实体不存在：{parts[0]}/{parts[1]}；使用实体 ID，不使用数组序号")
                parts[1] = str(index)
        target = candidate
        try:
            for part in parts[:-1]:
                if isinstance(target,list) and int(part)<0:
                    raise ValueError("数组下标不能为负数")
                target = target[int(part)] if isinstance(target,list) else target[part]
            key = int(parts[-1]) if isinstance(target,list) else parts[-1]
            if isinstance(key,int) and key<0:
                raise ValueError("数组下标不能为负数")
            if edit.op=="append":
                rows = target[key]
                if not isinstance(rows,list):
                    raise ValueError("append 的路径必须指向数组")
                rows.append(edit.value)
            elif edit.op=="remove":
                if isinstance(target,list) and not edit.reason.strip():
                    raise ValueError("删除实体需写明设计原因；不得删除用户要求的功能")
                del target[key]
            else:
                target[key] = edit.value
        except (KeyError,IndexError,TypeError) as exc:
            raise ValueError(f"修改路径不存在或类型不符：{edit.path}") from exc
    return candidate


def _summary(report, candidate):
    result = {key:deepcopy(report[key]) for key in ("valid","issues","coverage")}
    for issue in result["issues"]:
        issue["edit_paths"] = []
        for path in issue["paths"]:
            parts = path[1:].split("/")
            rows = candidate.get(parts[0],[])
            if parts[0] in COLLECTIONS and len(parts)>1 and parts[1].isdigit() and isinstance(rows,list):
                index = int(parts[1])
                if index<len(rows) and isinstance(rows[index],dict) and rows[index].get("id"):
                    parts[1] = rows[index]["id"]
            issue["edit_paths"].append("/"+"/".join(parts))
    result["defaults"] = report.get("defaults",[])
    if report.get("resolved") is not None:
        result["derived"] = {key:report["resolved"][key] for key in ("stairs","voids")}
    # 反馈实际当前值；不让模型依据历史坏稿猜下一次修改。
    ids = {entity for issue in report["issues"] for entity in issue.get("entities",[])}
    for issue in report["issues"]:
        actual = issue.get("actual")
        if isinstance(actual,dict):
            for frame in actual.values():
                if isinstance(frame,dict):
                    ids.update(frame.get("passable_opening_ids",[]))
    result["focus"] = {f"/{name}/{row['id']}":row for name in COLLECTIONS
        for i,row in enumerate(candidate.get(name,[]) if isinstance(candidate.get(name,[]),list) else [])
        if isinstance(row,dict) and row.get("id") in ids}
    return result


async def draft_design(*, base_prompt, user_request, diagnostics, current_plan=None,
                       thinking_mode=False, on_reasoning_delta=None):
    working, last_report, limits = deepcopy(current_plan), None, None
    sizing = []
    schemas = {
        "calculate_stair":_tool_schema("spec",StairSizing.model_json_schema()),
        "inspect_design":_tool_schema("design",DesignFacts.model_json_schema()),
        "revise_design":_tool_schema("changes",TypeAdapter(list[DesignEdit]).json_schema()),
    }
    diagnostics.update(prompt=base_prompt,user_request=user_request,current_plan=current_plan,
        tool_schema=schemas["inspect_design"],tool_schemas=schemas,model_calls=0,rounds=[],token_usage=None,settled=False)

    def inspect(candidate):
        nonlocal working, last_report, limits
        report = inspect_facts(candidate)
        working = report["document"] if report["document"] is not None else deepcopy(candidate)
        if report["document"] is not None:
            clearance = Clearances.model_validate(working.get("use_clearances",{})).model_dump()
            if limits is None:
                limits = clearance
            for key, minimum in limits.items():
                if clearance[key]<minimum:
                    report["issues"].append({"code":"lowered_clearance","paths":["/use_clearances/"+key],
                        "entities":[],"message":"不能降低已选净距消除错误","actual":clearance[key],"expected":minimum})
            report["valid"] = not report["issues"]
        last_report = _summary(report,working)
        diagnostics.update(last_candidate=deepcopy(working),last_inspection=last_report)
        return report

    @tool(args_schema=schemas["calculate_stair"])
    def stair_tool(spec: dict) -> dict:
        """布局前计算楼梯级数、占地和相对出口。spec.rise 为起止楼面高差。"""
        result = calculate_stair(spec)
        sizing.append(result)
        return result
    stair_tool.name = "calculate_stair"

    @tool(args_schema=schemas["inspect_design"])
    def inspect_tool(design: dict) -> dict:
        """提交完整 DesignFacts；程序生成编号/默认值并展开楼梯，检查通过即交付。"""
        return inspect(design)
    inspect_tool.name = "inspect_design"

    @tool(args_schema=schemas["revise_design"])
    def revise_tool(changes: list) -> dict:
        """按实体 ID 修改，如 /openings/entry/offset；程序保留其余数据并检查完整图纸。"""
        try:
            candidate = apply_design_edits(working,changes)
        except (ValueError,ValidationError) as exc:
            return {"valid":False,"issues":[{"code":"edit_error","paths":["/"],"entities":[],"message":str(exc)}],
                    "coverage":{"checked":[],"not_checked":["操作未应用，原图纸保持原状"]}}
        return inspect(candidate)
    revise_tool.name = "revise_design"

    for attempt in range(1,4):
        active = {t.name:t for t in ([stair_tool,inspect_tool] if working is None else [stair_tool,revise_tool])}
        context = {"current_design":working,"last_check":last_report,"stair_calculations":sizing}
        messages = [{"role":"system","content":base_prompt},
                    {"role":"user","content":user_request+"\n当前工作状态（null 表示尚未提交）：\n"+json.dumps(context,ensure_ascii=False)}]
        record = {"attempt":attempt,"available_tools":list(active)}
        diagnostics["rounds"].append(record)
        diagnostics["model_calls"] += 1
        try:
            llm = create_llm(enable_thinking=thinking_mode,streaming=bool(thinking_mode and on_reasoning_delta)).bind_tools(list(active.values()))
            with llm_trace_scope(stage="architecture.generate" if working is None else "architecture.revise_facts"):
                if thinking_mode and on_reasoning_delta:
                    async def emit(delta):
                        await on_reasoning_delta("architecture",delta)
                    reply = await stream_llm(llm,messages,on_reasoning_delta=emit)
                else:
                    reply = await invoke_llm(llm,messages,max_retries=0)
        except Exception:
            record["model_call_failed"] = True
            raise
        diagnostics["token_usage"] = merge_token_usage(diagnostics["token_usage"],reply.token_usage)
        record.update(output=reply.content,tool_calls=reply.tool_calls,invalid_tool_calls=reply.invalid_tool_calls,
                      call_id=reply.call_id,finish_reason=reply.finish_reason,token_usage=reply.token_usage,thinking=thinking_mode)
        calls = reply.tool_calls
        report = None
        if reply.finish_reason=="length" or reply.invalid_tool_calls:
            issue = "模型输出被截断或工具参数未形成合法 JSON"
        elif calls and (all(c["name"]=="calculate_stair" for c in calls) or len(calls)==1):
            issue = ""
            results = []
            for call in calls:
                if call["name"] not in active:
                    issue = "已有图纸时只调用 revise_design 局部修改，不重新输出整稿"
                    break
                result = active[call["name"]].invoke(call["args"])
                results.append({"name":call["name"],"result":result})
                if call["name"]!="calculate_stair":
                    report = result
            record["tool_results"] = results
        elif not calls and working is None:
            candidate = extract_json_object(reply.content or "",required_key=("volumes","levels"))
            if isinstance(candidate,dict):
                report,issue = inspect(candidate),""
            else:
                issue = "需要先调用 calculate_stair 或提交完整图纸"
        else:
            issue = "每轮只提交一次图纸/修订；多个独立楼梯计算可以同轮进行"
        if report is not None:
            record["inspection"] = last_report if "document" in report else report
            record["candidate"] = deepcopy(working)
            issue = "；".join(f"{','.join(row['paths'])}：{row['message']}" for row in report["issues"])
            if report["valid"]:
                diagnostics.update(settled=True,last_issue="")
                return report
            last_report = record["inspection"]
        elif issue:
            last_report = {"valid":False,"issues":[{"message":issue}]}
        record["issue"] = diagnostics["last_issue"] = issue or "已取得楼梯尺度，尚需提交完整图纸"
        if on_reasoning_delta:
            await on_reasoning_delta("architecture:progress",f"设计交接 {attempt}/3：{diagnostics['last_issue'][:300]}\n")
        if reply.finish_reason=="length":
            break
    return None

"""architecture：模型设计事实 → 统一工具检查和推导 → 输出图纸。"""

import time

from pydantic import ValidationError

from app.agent.generation.architecture.design_workflow import draft_design
from app.agent.state import GenerationState
from app.agent.prompts import build_architecture_plan_prompt
from app.agent.runtime import get_reasoning_callback
from app.design.facts import DesignFacts
from app.llm.errors import model_failure_result


async def architecture_planner(state: GenerationState) -> dict:
    started = time.perf_counter()
    feedback = str(state.get("design_feedback") or "").strip()
    callback = get_reasoning_callback()
    diagnostics = {"schema": "design-facts/2", "detail_level": state["detail_level"],
                   "profile": state["intent_profile"], "model_calls": 0, "settled": False}
    try:
        previous = None
        if feedback and state.get("design_document"):
            try:
                previous = DesignFacts.model_validate(state["design_document"]).model_dump(mode="json", exclude_unset=True)
            except ValidationError:
                diagnostics["last_issue"] = "上一张图纸不符合新版协议；请先重新生成新版图纸，再提交修改意见"
                return {"status": "failed", "error": diagnostics["last_issue"], "architecture_diag": diagnostics}
        prompt = build_architecture_plan_prompt(
            profile_id=state["intent_profile"], detail_level=state["detail_level"],
            style_preference=state.get("style_preference"),
        )
        if callback:
            await callback("architecture:progress", "正在设计空间与造型，再通过统一工具检查图纸……\n")
        accepted = await draft_design(
            base_prompt=prompt,
            user_request=state["user_message"]+("\n本轮修改意见："+feedback if feedback else ""),
            current_plan=previous, diagnostics=diagnostics,
            thinking_mode=state.get("thinking_mode") is not False, on_reasoning_delta=callback,
        )
    except Exception as exc:
        diagnostics.update(last_issue=str(exc), settled=False)
        if diagnostics.get("rounds"):
            diagnostics["rounds"][-1]["issue"] = str(exc)
        model_failed = bool(diagnostics.get("rounds") and diagnostics["rounds"][-1].get("model_call_failed"))
        failure = model_failure_result(exc) if model_failed else {"status": "failed", "error": "设计节点处理失败："+str(exc)}
        return {**failure, "architecture_diag": diagnostics}
    finally:
        diagnostics["total_ms"] = int((time.perf_counter()-started)*1000)

    if accepted is None:
        return {"status": "failed", "error": "建筑图纸未通过检查："+diagnostics["last_issue"],
                "architecture_diag": diagnostics}
    return {"design_document": accepted["document"], "resolved_design": accepted["resolved"],
            "architecture_diag": diagnostics, "design_review_status": "pending", "design_feedback": "", "error": None}
